-                (length_ - off) < tiling_->tileElements ? (length_ - off) : tiling_->tileElements);
-            CopyIn(off, count);
+        if (length_ == 0) return;
+        const uint32_t tile = tiling_->tileElements;
+        uint64_t off = 0;
+        uint32_t count = static_cast<uint32_t>(length_ < tile ? length_ : tile);
+        // Prologue: make the first tile available before entering the pipeline.
+        CopyIn(off, count);
+        while (off + tile < length_) {
+            const uint64_t next = off + tile;
+            const uint32_t nextCount = static_cast<uint32_t>(
+                (length_ - next) < tile ? (length_ - next) : tile);
+            // Two input queue entries allow prefetch before waiting on this tile.
+            CopyIn(next, nextCount);
             Compute(count);
             CopyOut(off, count);
+            off = next;
+            count = nextCount;
         }
+        // Drain: no speculative read beyond the last valid tile.
+        Compute(count);
+        CopyOut(off, count);
     }

