     const uint64_t useful = std::max<uint64_t>(1, (n + 4095) / 4096);
     t.blockNum = static_cast<uint32_t>(std::max<int64_t>(1, std::min<int64_t>(cores, useful)));
     t.blockLength = (n + t.blockNum - 1) / t.blockNum;
-    t.tileElements = 1024;
+    // Supplied Ascend910_9392 UB measurement. Reserve half for library and
+    // implementation overhead; the other half bounds all explicit buffers.
+    constexpr uint64_t measuredUbBytes = 196352;
+    constexpr uint64_t bufferBudget = measuredUbBytes / 2;
+    constexpr uint64_t alignElements = 64;
+    const uint64_t rawElementBytes = dtype == GELU_FLOAT32 ? 4 : 2;
+    // Two raw queues, three FP32 arrays, and five ERFC scratch arrays.
+    const uint64_t bytesPerElement = 2 * rawElementBytes + 8 * sizeof(float);
+    uint64_t tile = (bufferBudget / bytesPerElement / alignElements) * alignElements;
+    const auto maskBytes = [](uint64_t elements) {
+        return (((elements + 7) / 8 + 255) / 256) * 256;
+    };
+    while (tile * bytesPerElement + maskBytes(tile) > bufferBudget) {
+        tile -= alignElements;
+    }
+    const uint64_t usefulTile = std::max<uint64_t>(alignElements,
+        ((t.blockLength + alignElements - 1) / alignElements) * alignElements);
+    t.tileElements = static_cast<uint32_t>(std::min(tile, usefulTile));
     t.dtype = dtype;
     t.mode = mode;
     return t;

